import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";

// `RepoTarget` (from `./claudeConfig.helpers`, unresolvable in this sandbox) is just
// `{ local_path: string; full_name: string }` — inlined as a plain shape, no import needed.

const SAMPLE_REPOS = [
  { local_path: "/projects/bsc/base-studio-code", full_name: "kevin/base-studio-code" },
  { local_path: "/projects/northwind/api", full_name: "kevin/northwind-api" },
];

export function TargetSelector({
  allRepos = SAMPLE_REPOS, target = "global", setTarget = () => {},
}) {
  return (
    <Stack gap={6}>
      <Box className="mono-label">
        target
      </Box>
      <Row gap={6} align="stretch" wrap>
        {["global", ...allRepos.map((r) => r.local_path)].map((t) => {
          const isGlobal = t === "global";
          const label = isGlobal ? "global (~/.claude/)" : (allRepos.find((r) => r.local_path === t)?.full_name ?? t);
          const on = target === t;
          return (
            <Box
              key={t}
              className="mono"
              onClick={() => setTarget(t)}
              pad={[5, 12]} bg={on ? "var(--accent)" : "var(--bg-elev)"} radius={6} style={{ cursor: "pointer",
                fontSize: 11,
                color: on ? "var(--on-accent)" : "var(--fg-muted)",
                border: "1px solid " + (on ? "transparent" : "var(--border-soft)"),
                fontWeight: on ? 600 : 400,
              }}
            >{label}</Box>
          );
        })}
      </Row>
      {allRepos.length === 0 && (
        <Box className="mono-caption">
          Resolve repositories on the Projects board to unlock per-repo targets.
        </Box>
      )}
    </Stack>
  );
}
